import {addItem,countItem,removeItem} from './inventory.js';
const PREFIX='c5-side:';
export function chapterFiveErrands({p,slots,show,close,sync,sound,reward}){
 const has=id=>p.rewards.includes(PREFIX+id),mark=id=>{if(!has(id))p.rewards.push(PREFIX+id);sync()},active=id=>has(id+':accepted')&&!has(id+':done');
 function offer(id,name,text){show(name,text,[['Помогу',()=>{mark(id+':accepted');sound();close()}],['В другой раз',close]])}
 function finish(id,name,xp,item=null,count=1){const copy=slots.map(i=>i?{...i}:null);if(item&&!addItem(copy,item,count))return show(name,'Погоди, у тебя сумка битком. Награду придержу, только освободи место.');slots.splice(0,slots.length,...copy);reward(p,'c5-side-'+id,'quest',xp);mark(id+':done');sound();show(name,{axle:'Нашлась! Не представляешь, сколько я бы отдала за новую. Держи плату. И спасибо, что не спросил, как обозница потеряла ось.',lamps:'Оба фонаря горят. Теперь ученики смогут работать без ведра свечей. Скажешь Тару — ещё припишет это себе.',meal:'Поел? И даже спасибо передал? Ну вот, значит, ещё не совсем одичал. Твоя порция тоже готова.',herbs:'Цветы с дороги, а сколько радости. Пахнут лесом, а не дымом! Из этих я сделаю мазь. Тебе — лекарства и плата.'}[id])}
 function choices(n){const name=n.name;
  if(n.id==='c3-c5-caravan')return has('axle:done')?[]:!has('axle:accepted')?[['Есть ещё какая-нибудь работа?',()=>offer('axle',name,'У старой лесопилки сломалась телега. Ось я оттащила к обочине и в суматохе оставила. Найдёшь её у разбитой повозки — заплачу 35 золотых. Только не тащи всю телегу. Один такой уже был.')]]:has('axle:found')?[['Вернуть найденную ось',()=>finish('axle',name,600)]]:[];
  if(n.id==='c3-c5-smith')return has('lamps:done')?[]:!has('lamps:accepted')?[['Почему во дворе погасли фонари?',()=>offer('lamps',name,'Тар поставил рудные фонари и ушёл праздновать. Сердца в них не вставил. Нужно по сердцу голема на фонарь, всего два. Один у старой мастерской, второй у склада. Вставишь оба — дам 80 золотых. Да, за работу Тара плачу я. Не напоминай.')]]:has('lamps:0')&&has('lamps:1')?[['Оба фонаря починены',()=>finish('lamps',name,800,'greater_healing')]]:[];
  if(n.id==='c3-c5-witness')return has('meal:done')?[]:!has('meal:accepted')?[['Кому ты откладываешь этот обед?',()=>offer('meal',name,'Веду с лесопилки. «Я сам справлюсь», говорит, а потом суп из сухарей варит. Отнеси ему горячее, пока оно не превратилось в холодное. Он на Каменном разъезде, возле одинокого дома. Заплачу 45 золотых и тебя накормлю.')]]:has('meal:delivered')?[['Вед получил обед',()=>finish('meal',name,650,'hunter_stew')]]:[];
  if(n.id==='c3-c5-hermit')return active('meal')&&!has('meal:delivered')?[['Нара передала горячий обед',()=>{mark('meal:delivered');show(name,'Она опять? Я же сказал, сам… Ладно. Поставь сюда. И передай: соли в самый раз. Не «спасибо» передай, а про соль. Хотя… спасибо тоже передай.')}]]:[];
  if(n.id==='c3-c5-healer')return has('herbs:done')?[]:!has('herbs:accepted')?[['Тебе нужны травы?',()=>offer('herbs',name,'На разъезде ещё растёт серебряный первоцвет. Люди думают, он пропал без солнца, а он просто цветёт в темноте. Собери три образца: у северной сосны, старого пня и каменного уступа. Я отмечу их на карте. За находку дам 55 золотых и два зелья маны.')]]:[0,1,2].every(i=>has('herbs:'+i))?[['Передать три образца первоцвета',()=>finish('herbs',name,750,'mana_potion',2)]]:[];
  return [];
 }
 function interact(a){if(a.type==='c5-axle'){show('Ось у разбитой повозки',active('axle')?(mark('axle:found'),'Ось цела. Осталось вернуть её Борге.'):has('axle:found')?'Ось уже у тебя.':'Тяжёлая ось. Возможно, её кто-то ищет.');return true}
  if(a.type.startsWith('c5-lamp-')){const i=a.type.slice(-1);if(!active('lamps'))show('Рудный фонарь','В гнезде не хватает сердечника. Руна наверняка знает, какого.');else if(has('lamps:'+i))show('Рудный фонарь','Этот уже починен.');else if(!countItem(slots,'golem_core'))show('Рудный фонарь','Нужно рудное сердце голема.');else{removeItem(slots,'golem_core');mark('lamps:'+i);sound();show('Рудный фонарь','Сердце закреплено. За стеклом загорелся мягкий свет.')}return true}
  if(a.type.startsWith('c5-herb-')){const i=a.type.slice(-1);if(!active('herbs'))show('Серебряный первоцвет','Небольшие светлые цветы прячутся в траве.');else if(has('herbs:'+i))show('Серебряный первоцвет','Образец здесь уже собран.');else{mark('herbs:'+i);sound();show('Серебряный первоцвет','Образец бережно завёрнут для Сиэль.')}return true}return false;
 }
 function objective(){return [active('axle')?(has('axle:found')?'Забытая ось: вернитесь к Борге':'Забытая ось: осмотрите повозку у лесопилки'):'',active('lamps')?'Не заслуга Тара: почините фонари '+[0,1].filter(i=>has('lamps:'+i)).length+' / 2'+([0,1].every(i=>has('lamps:'+i))?' · вернитесь к Руне':''):'',active('meal')?(has('meal:delivered')?'Горячий обед: вернитесь к Наре':'Горячий обед: найдите Веда на лесопилке'):'',active('herbs')?'Цветы без солнца: образцы '+[0,1,2].filter(i=>has('herbs:'+i)).length+' / 3'+([0,1,2].every(i=>has('herbs:'+i))?' · вернитесь к Сиэль':''):''].filter(Boolean).join('\n')}
 function marker(id){const task={'c3-c5-caravan':'axle','c3-c5-smith':'lamps','c3-c5-witness':'meal','c3-c5-healer':'herbs'}[id];if(id==='c3-c5-hermit'&&active('meal')&&!has('meal:delivered'))return {symbol:'?',optional:true};if(!task||has(task+':done'))return null;const ready=task==='axle'?has('axle:found'):task==='lamps'?[0,1].every(i=>has('lamps:'+i)):task==='meal'?has('meal:delivered'):[0,1,2].every(i=>has('herbs:'+i));return {symbol:ready?'?':'!',optional:true}}
 return {choices,interact,objective,marker,flags:()=>({c5Errands:p.rewards.filter(id=>id.startsWith(PREFIX)).map(id=>id.slice(PREFIX.length))})};
}
